update sys_dict
dict_name = #{dictName}, dict_code = #{dictCode}, item_text = #{itemText}, item_value = #{itemValue}, sort = #{sort}, status = #{status}, update_time = #{updateTime}, update_user = #{updateUser},
where id = #{id}

mapper.select:
select id, dict_name, dict_code, item_text, item_value, sort, status, create_time, update_time, create_user, update_user from sys_dict
